 public static readonly string[] OfferedIds=Models.Select(m=>m.Id).ToArray();
 public static bool IsOffered(string id)=>OfferedIds.Contains(id);
 public static CatalogEntry[] Entries(string root,int mode,string model)=>AllEntries(root,mode,model).Where(m=>IsOffered(m.Id)).ToArray();
 public static CatalogModel Get(string id)=>Models.FirstOrDefault(m=>m.Id==id)??throw new ArgumentException("Модель не найдена в каталоге.");
 public static bool SamePath(string a,string b){try{return !string.IsNullOrWhiteSpace(a)&&!string.IsNullOrWhiteSpace(b)&&Path.GetFullPath(a).Equals(Path.GetFullPath(b),StringComparison.OrdinalIgnoreCase);}catch{return false;}}
 public static bool ContainsFile(string root,CatalogModel spec,string file){try{return !string.IsNullOrWhiteSpace(file)&&Path.GetFullPath(file).StartsWith(Path.GetFullPath(spec.Home(root))+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);}catch{return false;}}
 public static CatalogModel? Active(string root,int mode,string model)=>mode==2?Models.FirstOrDefault(m=>SamePath(m.ModelPath(root),model)):null;
 // Reject links in every ancestor and child before touching managed folders.
 public static void SafeHome(string root,CatalogModel spec){string home=Path.GetFullPath(spec.Home(root)),basePath=Path.GetFullPath(root)+Path.DirectorySeparatorChar;if(!home.StartsWith(basePath,StringComparison.OrdinalIgnoreCase))throw new IOException("Папка вне каталога NORA.");for(var d=new DirectoryInfo(home);d!=null;d=d.Parent){if((Directory.Exists(d.FullName)||File.Exists(d.FullName))&&(File.GetAttributes(d.FullName)&FileAttributes.ReparsePoint)!=0)throw new IOException("Папки-ссылки в каталоге моделей не поддерживаются.");}if(File.Exists(home))throw new IOException("Путь модели занят файлом.");if(Directory.Exists(home))CheckTree(home);}
 static void CheckTree(string dir){foreach(string p in Directory.EnumerateFileSystemEntries(dir)){var attr=File.GetAttributes(p);if((attr&FileAttributes.ReparsePoint)!=0)throw new IOException("Удаление/установка через ссылки запрещены.");if((attr&FileAttributes.Directory)!=0)CheckTree(p);}}
 public static bool Installed(string root,CatalogModel spec){SafeHome(root,spec);var p=spec.Paths(root);return File.Exists(p.Model)&&new FileInfo(p.Model).Length==spec.Bytes&&File.Exists(p.Server)&&File.Exists(p.CpuServer);}
 public static CatalogEntry[] AllEntries(string root,int mode,string model)=>Models.Select(m=>{try{bool installed=Installed(root,m),files=Directory.Exists(m.Home(root))&&Directory.EnumerateFileSystemEntries(m.Home(root)).Any();return new CatalogEntry(m.Id,m.Name,m.Description,m.Bytes,m.Thinking,installed,mode==2&&SamePath(model,m.ModelPath(root)),files,files&&!installed,"");}catch(Exception e){return new CatalogEntry(m.Id,m.Name,m.Description,m.Bytes,m.Thinking,false,false,false,false,e.Message);}}).ToArray();
 public static long UsedBytes(string root,IEnumerable<CatalogModel> specs){long total=0;foreach(var spec in specs){SafeHome(root,spec);if(Directory.Exists(spec.Home(root)))foreach(string p in Directory.EnumerateFiles(spec.Home(root),"*",SearchOption.AllDirectories))total=checked(total+new FileInfo(p).Length);}return total;}
 public static string[] Delete(string root,IEnumerable<CatalogModel> specs){var list=specs.ToArray();foreach(var s in list)SafeHome(root,s);var errors=new List<string>();foreach(var spec in list)try{SafeHome(root,spec);if(Directory.Exists(spec.Home(root)))Directory.Delete(spec.Home(root),true);}catch(Exception e){errors.Add(spec.Name+": "+e.Message);}return errors.ToArray();}
 public static async Task<DirectSetup.Result> Install(string root,CatalogModel spec,Action<string> progress,CancellationToken ct,HttpClient? transport=null,bool checkSpace=true){
  SafeHome(root,spec);ct.ThrowIfCancellationRequested();string home=spec.Home(root);Directory.CreateDirectory(home);var paths=spec.Paths(root);
  if(checkSpace&&!File.Exists(paths.Model)){long free=new DriveInfo(Path.GetPathRoot(Path.GetFullPath(home))!).AvailableFreeSpace,partial=File.Exists(paths.Model+".part")?new FileInfo(paths.Model+".part").Length:0;if(free<spec.Bytes-Math.Min(spec.Bytes,partial)+400_000_000)throw new IOException("Недостаточно места: освободи примерно "+((spec.Bytes+400_000_000)/1e9).ToString("F1")+" ГБ.");}
  using var own=transport==null?new HttpClient(new HttpClientHandler{AllowAutoRedirect=true}){Timeout=Timeout.InfiniteTimeSpan}:null;var client=transport??own!;if(own!=null)client.DefaultRequestHeaders.UserAgent.ParseAdd("NORA/2.6");
  progress(spec.Name+" · движок Vulkan (32 МБ)");await DirectSetup.Download(client,new Uri("https://github.com/ggml-org/llama.cpp/releases/download/b11669/llama-b11669-bin-win-vulkan-x64.zip"),Path.Combine(home,"vulkan.zip"),32182350,DirectSetup.VulkanHash,progress,ct);
  progress(spec.Name+" · резервный CPU-движок (20 МБ)");await DirectSetup.Download(client,new Uri("https://github.com/ggml-org/llama.cpp/releases/download/b11669/llama-b11669-bin-win-cpu-x64.zip"),Path.Combine(home,"cpu.zip"),19537886,DirectSetup.CpuHash,progress,ct);
  ct.ThrowIfCancellationRequested();SafeHome(root,spec);progress("Подготовка движка…");DirectSetup.Extract(Path.Combine(home,"vulkan.zip"),Path.GetDirectoryName(paths.Server)!);ct.ThrowIfCancellationRequested();DirectSetup.Extract(Path.Combine(home,"cpu.zip"),Path.GetDirectoryName(paths.CpuServer)!);
  progress(spec.Name+" · модель ("+(spec.Bytes/1e9).ToString("F2")+" ГБ)");await DirectSetup.Download(client,new Uri(spec.Url),paths.Model,spec.Bytes,spec.Sha256,progress,ct);ct.ThrowIfCancellationRequested();return paths;
 }
 public static async Task<bool> VerifyInstalled(string root,CatalogModel spec,Action<string> progress,CancellationToken ct){if(!Installed(root,spec))return false;progress("Проверка SHA-256 · "+spec.Name);bool valid=await DirectSetup.Verify(spec.ModelPath(root),spec.Bytes,spec.Sha256,ct)&&await DirectSetup.Verify(Path.Combine(spec.Home(root),"vulkan.zip"),32182350,DirectSetup.VulkanHash,ct)&&await DirectSetup.Verify(Path.Combine(spec.Home(root),"cpu.zip"),19537886,DirectSetup.CpuHash,ct);if(valid){ct.ThrowIfCancellationRequested();SafeHome(root,spec);DirectSetup.Extract(Path.Combine(spec.Home(root),"vulkan.zip"),Path.GetDirectoryName(spec.Paths(root).Server)!);ct.ThrowIfCancellationRequested();DirectSetup.Extract(Path.Combine(spec.Home(root),"cpu.zip"),Path.GetDirectoryName(spec.Paths(root).CpuServer)!);}return valid;}
